struct Rectangle {
    var width: Double
    var height: Double
    func area() -> Double {
        width * height
    }
}
let rect = Rectangle(width: 4.0, height: 5.0)
print(rect.area())

struct Point {
    var x: Double
    var y: Double
    mutating func reset() {
        self = Point(x: 0.0, y: 0.0)
    }
}
var p = Point(x: 10.0, y: 20.0)
p.reset()
print("(\(p.x), \(p.y))")

struct Size {
    var width: Double
    var height: Double
}
extension Size {
    init(square: Double) {
        self.init(width: square, height: square)
    }
}
let s = Size(square: 8.0)
print(s.width * s.height)

struct User {
    let name: String
    init?(name: String) {
        if name.isEmpty {
            return nil
        }
        self.name = name
    }
}
let user = User(name: "")
print(user == nil)

struct MathHelper {
