class Car {
    var speed: Int = 0
    func accelerate(by amount: Int) {
        speed += amount
    }
}
let car = Car()
car.accelerate(by: 35)
print(car.speed)

struct Age {
    let years: Int
    init?(years: Int) {
        if years < 0 {
            return nil
        }
        self.years = years
    }
}
let validAge = Age(years: 25)
print(validAge?.years ?? 0)

