struct StepCounter {
    var steps: Int = 0
    mutating func addSteps(_ count: Int) {
        steps += count
    }
}
var counter = StepCounter()
counter.addSteps(50)
print(counter.steps)

struct Person {
    var firstName: String
    var lastName: String
}
extension Person {
    init(fullName: String) {
        let parts = fullName.split(separator: " ")
        let first = String(parts.first ?? "")
        let last = parts.count > 1 ? String(parts[1]) : ""
        self.init(firstName: first, lastName: last)
    }
}
let person = Person(fullName: "Jane Doe")
print(person.firstName)

struct Username {
    let value: String
    init?(value: String) {
        if value.count < 3 {
            return nil
        }
        self.value = value
    }
}
let u = Username(value: "al")
print(u == nil)

